// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Restrict value to avoid overflow and ensure meaningful test
        value = bound(value, 0, address(c).balance);

        // Send some Ether to the contract so we can withdraw
        vm.deal(address(c), 1 ether);

        // Call sendMoney as owner
        vm.prank(c.owner());
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));

        // Now test withdrawAll behavior
        uint256 balanceBeforeWithdraw = address(c).balance;
        vm.prank(c.owner());
        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // The rule: withdrawAll should succeed only when the contract balance was zero (nothing to withdraw)
        assertTrue(withdrawSuccess == (balanceBeforeWithdraw == 0));
    }
}

